package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

public class TarUtils_parseOctal_TriageGen2Test {

    @Test
    public void testParseOctal_ValidSimple() {
        byte[] buffer = "000123".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 6);
        assertEquals(83L, result); // 123 octal = 1*64 + 2*8 + 3 = 83
    }

    @Test
    public void testParseOctal_WithLeadingSpaces() {
        byte[] buffer = "   0755".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 8);
        assertEquals(493L, result); // 755 octal = 7*64 + 5*8 + 5 = 493
    }

    @Test
    public void testParseOctal_WithTrailingSpacesAndNulls() {
        byte[] buffer = "010  \0\0".getBytes();
        // length is 8: '0','1','0',' ',' ','\0','\0' (assuming \0 is 0 byte)
        // The logic trims trailing spaces and nulls
        long result = TarUtils.parseOctal(buffer, 0, 7);
        assertEquals(8L, result);
    }

    @Test
    public void testParseOctal_FirstByteIsZero() {
        byte[] buffer = new byte[5];
        buffer[0] = 0;
        buffer[1] = '1';
        long result = TarUtils.parseOctal(buffer, 0, 5);
        assertEquals(0L, result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_LengthTooSmall() {
        byte[] buffer = "0".getBytes();
        TarUtils.parseOctal(buffer, 0, 1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidOctalDigit() {
        byte[] buffer = "089".getBytes(); // 8 and 9 are invalid octal
        TarUtils.parseOctal(buffer, 0, 3);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_NonDigitCharacter() {
        byte[] buffer = "01A".getBytes();
        TarUtils.parseOctal(buffer, 0, 3);
    }

    @Test
    public void testParseOctal_WithInternalNull() {
        // If a null byte is encountered inside the loop after start, it breaks
        byte[] buffer = "01\002".getBytes(); 
        // start=0, end=4. 
        // loop: start=0 ('0'), start=1 ('1'), start=2 ('\0') -> break
        long result = TarUtils.parseOctal(buffer, 0, 4);
        assertEquals(1L, result);
    }

    @Test
    public void testParseOctal_OffsetHandling() {
        byte[] buffer = "ABC0123XYZ".getBytes();
        // '0123' starts at index 3
        long result = TarUtils.parseOctal(buffer, 3, 4);
        assertEquals(83L, result);
    }

    @Test
    public void testParseOctal_TrailingSpacesOnly() {
        // Testing the while loop for end--
        byte[] buffer = "012  ".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 5);
        assertEquals(10L, result);
    }

    @Test
    public void testParseOctal_LargeValue() {
        // Test max long range within octal limits
        // 777777777777777777 (octal)
        byte[] buffer = "777777777777777777".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, buffer.length);
        // Verification of bit shifting logic
        long expected = 0;
        for (byte b : buffer) {
            expected = (expected << 3) + (b - '0');
        }
        assertEquals(expected, result);
    }
}
